import 'package:equatable/equatable.dart';
class AcademicClassEntity extends Equatable { const AcademicClassEntity({required this.id,required this.name,required this.isActive,required this.createdAt,required this.updatedAt}); final String id,name; final bool isActive; final DateTime createdAt,updatedAt; AcademicClassEntity copyWith({String? id,String? name,bool? isActive,DateTime? createdAt,DateTime? updatedAt})=>AcademicClassEntity(id:id??this.id,name:name??this.name,isActive:isActive??this.isActive,createdAt:createdAt??this.createdAt,updatedAt:updatedAt??this.updatedAt); @override List<Object?> get props=>[id,name,isActive,createdAt,updatedAt]; }
